from ninja import Router, Depends
from ninja.security import HttpBearer
from ninja.errors import HttpError
from django.http import Http404
from .models import VehicleAsset
from .schemas import GPSCoordinatesSchema

class BearerAuth(HttpBearer):
    def authenticate(self, request, token):
        if token.startswith("logistics_"):
            return {"carrier_id": token.split("_")[1]}
        return None

fleet_router = Router(auth=BearerAuth())

class VehicleLocatorService:
    async def get_carrier_vehicle(self, request, vin: str) -> VehicleAsset:
        try:
            vehicle = await VehicleAsset.objects.aget(vin=vin)
        except VehicleAsset.DoesNotExist:
            raise Http404("Vehicle not found")

        # Verify carrier ownership
        if str(vehicle.carrier_company_id) != str(request.auth.get("carrier_id")):
            raise HttpError(403, "Access to vehicle telemetry forbidden for this carrier")

        return vehicle

@fleet_router.get("/fleet/{vin}/live-gps", response=GPSCoordinatesSchema)
async def get_vehicle_live_gps(request, vin: str, locator: VehicleLocatorService = Depends()):
    vehicle = await locator.get_carrier_vehicle(request, vin)
    return {
        "vin": vehicle.vin,
        "latitude": vehicle.current_latitude,
        "longitude": vehicle.current_longitude,
        "speed_kmh": vehicle.current_speed
    }
